def objective_lgbm(trial):
    params = {
        "objective": "binary",
        "metric": "binary_logloss",
        "verbosity": -1,
        "boosting_type": "gbdt",
        "n_estimators": trial.suggest_int("n_estimators", 800, 1500),  # Daha dar aralık
        "learning_rate": trial.suggest_float("learning_rate", 0.01, 0.1, log=True),  # Aşırı küçük ve büyük değerler engellendi
        "num_leaves": trial.suggest_int("num_leaves", 31, 128),  # Varsayılan 31'e yakın, kontrollü büyüklükte
        "max_depth": trial.suggest_int("max_depth", 3, 12),  # Aşırı derin ağaçlardan kaçınıldı
        "min_data_in_leaf": trial.suggest_int("min_data_in_leaf", 20, 80),  # Overfitting'i engeller
        "lambda_l1": trial.suggest_float("lambda_l1", 1e-3, 1.0, log=True),  # 10 yerine 1'e kadar
        "lambda_l2": trial.suggest_float("lambda_l2", 1e-3, 1.0, log=True),
        "colsample_bytree": trial.suggest_float("colsample_bytree", 0.7, 1.0),  # 0.7 altına düşmemesi daha stabil
        "subsample": trial.suggest_float("subsample", 0.7, 1.0),
        "feature_fraction": trial.suggest_float("feature_fraction", 0.7, 1.0),
        "bagging_fraction": trial.suggest_float("bagging_fraction", 0.7, 1.0),
        "bagging_freq": trial.suggest_int("bagging_freq", 5, 30),  # 1 çok sık olabilir, 30 daha dengeli
        "random_state": 42,
    }

    model = LGBMClassifier(**params)
    scores = cross_val_score(model, train[FEATURES], train['Sex_F'], cv=5, scoring="roc_auc")
    return np.mean(scores)



